#!/usr/bin/env bash
# SPDX-FileCopyrightText: 2026 Kation contributors
# SPDX-License-Identifier: GPL-2.0-or-later

# Tests the package scripts generated by cmake/KationPackaging.cmake (from
# packaging/user-sessions.sh), with fake systemctl and timeout commands that log
# their arguments. Run by ctest with the build folder as argument.

set -euo pipefail

BUILD=${1:?usage: test-package-scripts.sh BUILD_DIR}
SCRIPTS="$BUILD/packaging"
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT
FAILURES=0

fail() {
    echo "FAIL: $*" >&2
    FAILURES=$((FAILURES + 1))
}

# Fake commands: two user managers, and a unit name that is not a user manager.
mkdir -p "$WORK/bin" "$WORK/empty"
cat >"$WORK/bin/systemctl" <<'EOF'
#!/bin/sh
echo "$*" >>"$KATION_TEST_LOG"
case "$1" in
list-units)
    [ -z "${FAIL_LIST:-}" ] || exit 1
    printf '%s\n' 'user@1000.service loaded active running User Manager for UID 1000' \
        'user@1001.service loaded active running User Manager for UID 1001' \
        'user@x.service loaded active running Not a user manager'
    exit 0
    ;;
esac
# FAIL_ALL: every call in the users' managers fails.
[ -z "${FAIL_ALL:-}" ] || exit 1
EOF
cat >"$WORK/bin/timeout" <<'EOF'
#!/bin/sh
shift
exec "$@"
EOF
chmod +x "$WORK/bin/systemctl" "$WORK/bin/timeout"

UPGRADE="list-units --state=running --plain --no-legend user@*.service
--user -M 1000@ daemon-reload
--user -M 1000@ try-restart --no-block kationd.service
--user -M 1001@ daemon-reload
--user -M 1001@ try-restart --no-block kationd.service"
REMOVE="list-units --state=running --plain --no-legend user@*.service
--user -M 1000@ stop --no-block kationd.service
--user -M 1000@ daemon-reload
--user -M 1001@ stop --no-block kationd.service
--user -M 1001@ daemon-reload"

# check NAME EXPECTED_LOG [ENV=VALUE...] -- COMMAND...: runs COMMAND with only
# the fake commands on PATH, then compares the systemctl calls it made.
check() {
    local name=$1 expected=$2 status=0
    shift 2
    local env=()
    while [ "$1" != -- ]; do
        env+=("$1")
        shift
    done
    shift
    local log="$WORK/$name.log"
    : >"$log"
    env -i PATH="$WORK/bin" KATION_TEST_LOG="$log" "${env[@]}" "$@" >"$WORK/$name.out" 2>&1 || status=$?
    [ "$status" -eq 0 ] || fail "$name: exit status $status ($(cat "$WORK/$name.out"))"
    [ "$(cat "$log")" = "$expected" ] || fail "$name: systemctl calls were:
$(cat "$log")
expected:
$expected"
}

for script in deb/postinst deb/prerm rpm/posttrans rpm/preun; do
    [ -x "$SCRIPTS/$script" ] || fail "$script is missing or not executable"
done
[ -f "$BUILD/arch/kation.install" ] || fail "arch/kation.install is missing"
grep -q '^install=kation.install$' "$BUILD/arch/PKGBUILD" || fail "the PKGBUILD does not name kation.install"

check deb-configure "$UPGRADE" -- /bin/sh "$SCRIPTS/deb/postinst" configure 0.3.0
check deb-abort "" -- /bin/sh "$SCRIPTS/deb/postinst" abort-upgrade 0.4.0
check deb-remove "$REMOVE" -- /bin/sh "$SCRIPTS/deb/prerm" remove
check deb-upgrade "" -- /bin/sh "$SCRIPTS/deb/prerm" upgrade 0.4.0
check rpm-posttrans "$UPGRADE" -- /bin/sh "$SCRIPTS/rpm/posttrans"
check rpm-erase "$REMOVE" -- /bin/sh "$SCRIPTS/rpm/preun" 0
check rpm-upgrade "" -- /bin/sh "$SCRIPTS/rpm/preun" 1
# pacman sources the install script with bash and calls one function.
for call in "post_install 0.4.0-1" "post_upgrade 0.4.0-1 0.3.0-1"; do
    check "arch-${call%% *}" "$UPGRADE" -- /bin/bash -c ". '$BUILD/arch/kation.install'; $call"
done
check arch-pre_remove "$REMOVE" -- /bin/bash -c ". '$BUILD/arch/kation.install'; pre_remove 0.4.0-1"

# Never fails the package operation: no systemd (a container), failing calls, no systemctl.
check no-systemd "list-units --state=running --plain --no-legend user@*.service" FAIL_LIST=1 -- \
    /bin/sh "$SCRIPTS/deb/postinst" configure
check failing-calls "$UPGRADE" FAIL_ALL=1 -- /bin/sh "$SCRIPTS/rpm/posttrans"
: >"$WORK/missing.log"
status=0
env -i PATH="$WORK/empty" /bin/sh "$SCRIPTS/deb/prerm" remove >"$WORK/missing.out" 2>&1 || status=$?
[ "$status" -eq 0 ] || fail "without systemctl: exit status $status ($(cat "$WORK/missing.out"))"

if [ "$FAILURES" -gt 0 ]; then
    echo "$FAILURES failure(s)" >&2
    exit 1
fi
echo "All package script checks passed."
